"""Хранилище: JSON-файл с HMAC-подписью.

Файл = {"payload": {...}, "sig": "<hex HMAC-SHA256>"}. Ключ лежит ВНЕ проекта
(env TODO_SECRET_KEY или ~/.todo_demo/secret.key, права 0600). Кто не знает ключ,
не может подделать файл: любая ручная правка ломает подпись, приложение отказывается
читать такую БД и НЕ перезаписывает её. Это защита от подделки, не шифрование.
Не защищает от подмены файла на старую валидную копию (rollback).
"""
from __future__ import annotations

import hashlib
import hmac
import json
import os
import secrets
import tempfile
import threading
from pathlib import Path

DEFAULT_DB = "todo_db.json"
DEFAULT_KEY_FILE = Path.home() / ".todo_demo" / "secret.key"


class StoreTamperedError(RuntimeError):
    """Файл БД повреждён или изменён вне приложения."""


def load_key(key: "str | None" = None, key_file: Path = DEFAULT_KEY_FILE) -> bytes:
    key = key or os.environ.get("TODO_SECRET_KEY")
    if key:
        return key.encode("utf-8")
    key_file = Path(key_file)
    if not key_file.exists():
        key_file.parent.mkdir(parents=True, exist_ok=True)
        fd = os.open(key_file, os.O_WRONLY | os.O_CREAT | os.O_EXCL, 0o600)
        with os.fdopen(fd, "w") as f:
            f.write(secrets.token_hex(32))
    return key_file.read_text().strip().encode("utf-8")


def _canonical(payload: dict) -> bytes:
    return json.dumps(payload, sort_keys=True, ensure_ascii=False, separators=(",", ":")).encode("utf-8")


class SignedJsonStore:
    def __init__(self, path: str, key: bytes):
        if not key:
            raise ValueError("пустой ключ подписи")
        self.path = Path(path)
        self._key = key
        self.lock = threading.RLock()

    def _sign(self, payload: dict) -> str:
        return hmac.new(self._key, _canonical(payload), hashlib.sha256).hexdigest()

    def load(self, default: dict) -> dict:
        if not self.path.exists():
            return default
        try:
            doc = json.loads(self.path.read_text(encoding="utf-8"))
            payload, sig = doc["payload"], doc["sig"]
            ok = isinstance(payload, dict) and isinstance(sig, str)
        except (ValueError, KeyError, TypeError, OSError):
            ok = False
        if not ok or not hmac.compare_digest(sig, self._sign(payload)):
            raise StoreTamperedError(
                f"проверка целостности БД {self.path} не пройдена: файл изменён вне приложения или повреждён")
        return payload

    def save(self, payload: dict) -> None:
        doc = {"payload": payload, "sig": self._sign(payload)}
        # атомарная запись: временный файл + rename, чтобы не оставить половину файла
        fd, tmp = tempfile.mkstemp(dir=self.path.parent or ".", prefix=".todo_", suffix=".tmp")
        try:
            with os.fdopen(fd, "w", encoding="utf-8") as f:
                json.dump(doc, f, ensure_ascii=False, indent=2)
            os.replace(tmp, self.path)
        finally:
            if os.path.exists(tmp):
                os.unlink(tmp)

"""Ядро TODO: вся бизнес-логика. Не знает про HTTP.

Контракт (см. week_01): ошибки ввода — ValueError / NotFound, при ошибке состояние не меняется.
Удаление выполняется сразу: подтверждение у пользователя спрашивает MCP-сервер (Elicitation).
"""
from __future__ import annotations

from dataclasses import dataclass
from datetime import date, datetime
from typing import List, Optional

from .store import SignedJsonStore

MAX_TITLE_LEN = 200
PRIORITIES = ("low", "normal", "high")
_UNSET = object()


class NotFound(ValueError):
    def __init__(self, what: str, obj_id):
        super().__init__(f"{what} {obj_id} не найдена")
        self.obj_id = obj_id


def TaskNotFound(task_id):
    return NotFound("задача", task_id)


@dataclass(frozen=True)
class Task:
    id: int
    title: str
    done: bool
    priority: str
    due: Optional[str]
    created_at: str

    def as_dict(self) -> dict:
        return dict(self.__dict__)


def normalize_title(title) -> str:
    if not isinstance(title, str):
        raise ValueError("название задачи должно быть строкой")
    title = title.strip()
    if not title:
        raise ValueError("название задачи не может быть пустым")
    if len(title) > MAX_TITLE_LEN:
        raise ValueError(f"название задачи не может быть длиннее {MAX_TITLE_LEN} символов")
    return title


def normalize_priority(priority) -> str:
    if priority not in PRIORITIES:
        raise ValueError(f"приоритет должен быть одним из: {', '.join(PRIORITIES)}")
    return priority


def normalize_due(due) -> Optional[str]:
    if due is None or (isinstance(due, str) and not due.strip()):
        return None
    if not isinstance(due, str):
        raise ValueError("срок должен быть строкой YYYY-MM-DD")
    try:
        return date.fromisoformat(due.strip()).isoformat()
    except ValueError:
        raise ValueError("срок должен быть корректной датой в формате YYYY-MM-DD") from None


def _check_id(obj_id) -> int:
    if isinstance(obj_id, bool) or not isinstance(obj_id, int):
        raise ValueError("id должен быть целым числом")
    return obj_id


def _task(d: dict) -> Task:
    return Task(d["id"], d["title"], d["done"], d["priority"], d["due"], d["created_at"])


class TodoService:
    def __init__(self, store: SignedJsonStore):
        self._store = store

    # --- внутреннее: транзакция «загрузить → изменить → сохранить» ---
    @staticmethod
    def _empty() -> dict:
        return {"next_id": 1, "tasks": []}

    def _load(self) -> dict:
        return self._store.load(self._empty())

    def _find(self, db: dict, task_id) -> dict:
        task_id = _check_id(task_id)
        for t in db["tasks"]:
            if t["id"] == task_id:
                return t
        raise TaskNotFound(task_id)

    # --- задачи ---
    def add_task(self, title, priority="normal", due=None) -> Task:
        title, priority, due = normalize_title(title), normalize_priority(priority), normalize_due(due)
        with self._store.lock:
            db = self._load()
            t = {"id": db["next_id"], "title": title, "done": False, "priority": priority,
                 "due": due, "created_at": datetime.now().isoformat(timespec="seconds")}
            db["next_id"] += 1
            db["tasks"].append(t)
            self._store.save(db)
            return _task(t)

    def get_task(self, task_id) -> Task:
        with self._store.lock:
            return _task(self._find(self._load(), task_id))

    def list_tasks(self, done: Optional[bool] = None) -> List[Task]:
        with self._store.lock:
            tasks = [_task(t) for t in self._load()["tasks"]]
        return [t for t in tasks if done is None or t.done == done]

    def edit_task(self, task_id, title=_UNSET, priority=_UNSET, due=_UNSET, done=_UNSET) -> Task:
        """Меняет только переданные поля. Всё валидируется до записи."""
        changes = {}
        if title is not _UNSET:
            changes["title"] = normalize_title(title)
        if priority is not _UNSET:
            changes["priority"] = normalize_priority(priority)
        if due is not _UNSET:
            changes["due"] = normalize_due(due)
        if done is not _UNSET:
            if not isinstance(done, bool):
                raise ValueError("done должно быть true или false")
            changes["done"] = done
        with self._store.lock:
            db = self._load()
            t = self._find(db, task_id)
            t.update(changes)
            self._store.save(db)
            return _task(t)

    def complete_task(self, task_id) -> Task:
        """Идемпотентно."""
        return self.edit_task(task_id, done=True)

    def delete_task(self, task_id) -> Task:
        """Удаляет задачу и возвращает её (удобно для сообщения пользователю)."""
        with self._store.lock:
            db = self._load()
            t = self._find(db, task_id)
            db["tasks"].remove(t)
            self._store.save(db)
            return _task(t)

"""Flask-приложение: REST API (/api/...) + одностраничный UI (/).

Запуск: python -m todo.web [--port 5000] [--db todo_db.json]
Удаление выполняется сразу; подтверждение спрашивает MCP-сервер (Elicitation), а не приложение.
"""
from __future__ import annotations

import argparse

from flask import Flask, jsonify, render_template, request

from .service import NotFound, TodoService
from .store import DEFAULT_DB, SignedJsonStore, StoreTamperedError, load_key


def create_app(db_path: str = DEFAULT_DB, key: "str | None" = None) -> Flask:
    app = Flask(__name__)
    service = TodoService(SignedJsonStore(db_path, load_key(key)))
    app.config["service"] = service

    def err(message: str, status: int):
        return jsonify({"error": message}), status

    @app.errorhandler(NotFound)
    def _nf(e):
        return err(str(e), 404)

    @app.errorhandler(ValueError)
    def _bad(e):
        return err(str(e), 400)

    @app.errorhandler(StoreTamperedError)
    def _tampered(e):
        return err(str(e), 500)

    @app.errorhandler(404)
    def _404(e):
        return err("не найдено", 404)

    @app.errorhandler(405)
    def _405(e):
        return err("метод не поддерживается", 405)

    def body() -> dict:
        data = request.get_json(silent=True)
        if not isinstance(data, dict):
            raise ValueError("тело запроса должно быть JSON-объектом")
        return data

    @app.get("/")
    def index():
        return render_template("index.html")

    @app.get("/api/tasks")
    def list_tasks():
        flag = request.args.get("done")
        if flag not in (None, "true", "false"):
            raise ValueError("параметр done должен быть true или false")
        done = None if flag is None else flag == "true"
        return jsonify([t.as_dict() for t in service.list_tasks(done)])

    @app.post("/api/tasks")
    def add_task():
        d = body()
        t = service.add_task(d.get("title"), d.get("priority", "normal"), d.get("due"))
        return jsonify(t.as_dict()), 201

    @app.get("/api/tasks/<int:task_id>")
    def get_task(task_id):
        return jsonify(service.get_task(task_id).as_dict())

    @app.patch("/api/tasks/<int:task_id>")
    def edit_task(task_id):
        d = body()
        fields = {k: d[k] for k in ("title", "priority", "due", "done") if k in d}
        if not fields:
            raise ValueError("нет полей для изменения (title, priority, due, done)")
        return jsonify(service.edit_task(task_id, **fields).as_dict())

    @app.post("/api/tasks/<int:task_id>/complete")
    def complete_task(task_id):
        return jsonify(service.complete_task(task_id).as_dict())

    @app.delete("/api/tasks/<int:task_id>")
    def delete_task(task_id):
        return jsonify({"status": "deleted", "task": service.delete_task(task_id).as_dict()})

    return app


def main() -> None:
    p = argparse.ArgumentParser(description="TODO web demo")
    p.add_argument("--port", type=int, default=5000)
    p.add_argument("--db", default=DEFAULT_DB)
    args = p.parse_args()
    create_app(args.db).run(host="127.0.0.1", port=args.port)


if __name__ == "__main__":
    main()
